-- 039: BLPD checked against vatican.va and corrected (#185, #191, #192).
--
-- BLPD's text is © Fundación Palabra de Vida / Editorial Verbo Divino (vatican.va:
-- © Libreria Editrice Vaticana) and licensed to BibleGet for the API, not for
-- publication, so the data half of this migration lives in the private archive
-- BibleGet-I-O/BLPD-vatican: apply its migrations/039-blpd-from-archive.sql
-- FIRST (generated by its scripts/migration.py; see its README). This public
-- half checks that the table holds exactly that content and rebuilds BLPD_idx.
--
-- What the archive changed (from BibleGet's table, against vatican.va
-- archive/ESL0506, the source BLPD was imported from):
--   * 300 verses take vatican.va's wording: typos, agreement, dropped or
--     duplicated words, verses cut short in the 2015 import;
--   * 18 chapters follow vatican.va's verse division and printed displacements
--     (lettered half-lines: Gen 47:5a, 6b, 5b; Ps 37:14c, 34b, 40b; Za 4:6a-6b,
--     10a-10b; ...; 1 Co 16:5-6 split; Gen 47:5-6 no longer stored twice);
--   * Job 42, Isaiah 65-66 and Jeremiah 51-52, missing since the import, added;
--   * a Greek text of Esther (verseorigin GREEK), stored like NABRE and NVBSE:
--     the canonical verses repeat the Hebrew text, the Greek additions sit at
--     their places (1:1a-1r, 3:13a-g, 4:8b, 4:17a-ff, the Greek 5:1-2 with
--     5:1a-1k and 5:2a-2d, 8:12a-v, 10:3a-l).
-- Rows whose text is unchanged keep their embeddings; re-embed BLPD afterwards
-- (compute_embeddings.py --version BLPD, default column and --column embedding).
--
-- BLPD_idx: chapters, verses_count (distinct verse numbers per chapter) and
-- verses_last per book, from the rows. Esther lists its ten chapters twice
-- (chapters = 20), as NABRE_idx and NVBSE_idx do for their two texts.

BEGIN;

DO $mig$
DECLARE
    digest TEXT;
BEGIN
    SELECT md5(string_agg(concat_ws('|', book, chapter, verse, coalesce(verseequiv, ''), coalesce(verseorigin, ''), text),
                          E'\n' ORDER BY "verseID")) INTO digest FROM "BLPD";
    IF digest <> 'eec6f418d1e12d7ef60322a293275f12' OR (SELECT count(*) FROM "BLPD") <> 35735 THEN
        RAISE EXCEPTION 'BLPD does not hold the BLPD-vatican archive''s text (md5 %): apply BLPD-vatican/migrations/039-blpd-from-archive.sql first', digest;
    END IF;

    UPDATE "BLPD_idx" i SET chapters = x.chapters, verses_count = x.cnt, verses_last = x.last
    FROM (
        SELECT book,
               CASE WHEN book = 19 THEN 2 * count(*) ELSE count(*) END AS chapters,
               CASE WHEN book = 19 THEN string_agg(d::text, ',' ORDER BY chapter) || ',' || string_agg(d::text, ',' ORDER BY chapter)
                    ELSE string_agg(d::text, ',' ORDER BY chapter) END AS cnt,
               CASE WHEN book = 19 THEN string_agg(m::text, ',' ORDER BY chapter) || ',' || string_agg(m::text, ',' ORDER BY chapter)
                    ELSE string_agg(m::text, ',' ORDER BY chapter) END AS last
        FROM (SELECT book, chapter, count(DISTINCT verse) AS d, max(verse) AS m FROM "BLPD" GROUP BY book, chapter) c
        GROUP BY book
    ) x
    WHERE i.book = x.book
      AND (i.chapters, i.verses_count, i.verses_last) IS DISTINCT FROM (x.chapters, x.cnt, x.last);
END
$mig$;

COMMIT;
